DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_single_iterative` ()   BEGIN
    DECLARE i INT DEFAULT 1;
    WHILE i <= 10000 DO
        INSERT INTO user_activity_logs (user_id, activity_type, ip_address)
        VALUES (i, 'LOGIN', '192.168.1.1');
        SET i = i + 1;
    END WHILE;
END$$

